window.SCHOOL_LISTENING={"../assets/media/fd97f00863036b1cde7b2f95a2505a5a253a90dd2702c90720afb1370c645421.mp3":[{"id":"PPT_fd97f00863036b1c","audioId":"PPT_fd97f00863036b1c","title":"Book 2 · Unit 5 · RW · READING 1","subtitle":"READING 1 · source slide 43","duration":189.65,"cues":[{"start":0,"end":3.22,"text":"Sporting news Home","coverage":1},{"start":4,"end":4.9,"text":"About","coverage":1},{"start":6,"end":6.54,"text":"News","coverage":1},{"start":7.94,"end":8.44,"text":"Contact","coverage":1},{"start":9.82,"end":13.12,"text":"More Five unusual sports","coverage":1},{"start":13.64,"end":17.28,"text":"The most unusual sports from around the world.","coverage":1},{"start":18.44,"end":20.66,"text":"Every country has a national sport,","coverage":1},{"start":21.2,"end":25,"text":"and most popular sports are now played across the world.","coverage":1},{"start":25,"end":28.86,"text":"Most people have heard of sports like football,","coverage":1},{"start":29.34,"end":29.74,"text":"basketball,","coverage":1},{"start":30.08,"end":30.42,"text":"baseball,","coverage":1},{"start":30.74,"end":31.34,"text":"and cricket.","coverage":1},{"start":31.96,"end":32.48,"text":"However,","coverage":1},{"start":32.82,"end":39.78,"text":"in most countries, people also play unusual sports with strange and interesting rules.","coverage":1},{"start":40.56,"end":45.34,"text":"Here are our top five unusual sports from around the world.","coverage":1},{"start":47.34,"end":54.1,"text":"Coney Island Polar Bear Plunge People go swimming in the Atlantic Ocean in the winter.","coverage":1},{"start":54.1,"end":64.42,"text":"They go swimming at the beach on Coney Island in New York City every Sunday from October to April and also on New Year's Day.","coverage":1},{"start":65.1,"end":69.6,"text":"The water temperature can drop to as low as zero degrees Centigrade.","coverage":1},{"start":70.28,"end":73.46,"text":"Sometimes there is snow and cold wind,","coverage":1},{"start":73.92,"end":74,"text":"too.","coverage":1},{"start":74.9,"end":79.26,"text":"People believe that swimming in the cold water is good for their health.","coverage":1},{"start":79.26,"end":83.26,"text":"The club started in 1903.","coverage":1},{"start":85.54,"end":89.52,"text":"Dragon Boat Racing Every year in Singapore,","coverage":1},{"start":90.24,"end":93.38,"text":"thousands of people come to watch the Dragon Boat Race.","coverage":1},{"start":94.3,"end":100.26,"text":"A dragon boat is a traditional Chinese boat with a painted dragon's head on one end.","coverage":1},{"start":100.94,"end":105.58,"text":"There are 22 people in each boat, and they race in the water.","coverage":1},{"start":105.58,"end":110.08,"text":"Dragon Boat Racing is also popular in China,","coverage":1},{"start":110.44,"end":110.94,"text":"Malaysia,","coverage":1},{"start":111.3,"end":112.52,"text":"and Indonesia.","coverage":1},{"start":114.44,"end":122.96,"text":"Caber Toss In this sport, people compete by throwing a large piece of wood called a caber as far as they can.","coverage":1},{"start":123.56,"end":126.5,"text":"The caber toss is an ancient Scottish sport.","coverage":1},{"start":127.1,"end":128.02,"text":"The caber has","coverage":1},{"start":128.02,"end":128.48,"text":"no","coverage":1},{"start":128.48,"end":133.28,"text":"official size or shape, but it is usually the size of a small tree.","coverage":1},{"start":136.02,"end":142.28,"text":"Fireball Football Students in Indonesia play this game to welcome the month of Ramadan.","coverage":1},{"start":142.96,"end":144.52,"text":"It is similar to football.","coverage":1},{"start":145.14,"end":147.46,"text":"The ball is made from coconut shells.","coverage":1},{"start":148.24,"end":154.64,"text":"Before starting the game, players pour salt on themselves and then set the ball on fire.","coverage":1},{"start":155.4,"end":158.2,"text":"The ball is on fire throughout the game,","coverage":1},{"start":158.54,"end":161.22,"text":"and the players play with their bare feet.","coverage":1},{"start":163.12,"end":165.84,"text":"Toe Wrestling In England,","coverage":1},{"start":166.18,"end":169.04,"text":"toe wrestling started in the 1970s.","coverage":1},{"start":169.48,"end":174.9,"text":"The World Toe Wrestling Competition takes place every year in Wetland, Derbyshire.","coverage":1},{"start":175.52,"end":183.36,"text":"In the sport, two people fight with their bare feet, each player trying to push the other player's foot flat on the floor.","coverage":1},{"start":183.92,"end":187.76,"text":"Players must keep both hands on the floor during the fight.","coverage":1}],"file":"87ad122513dbcaaf5061.js","track":0,"media":"../assets/media/fd97f00863036b1cde7b2f95a2505a5a253a90dd2702c90720afb1370c645421.mp3"}],"../assets/media/2eee55d68d2335b8c2a38da0f3fe7608bdbd4ace96a2ce76213cff026d4629a4.mp3":[{"id":"PPT_2eee55d68d2335b8","audioId":"PPT_2eee55d68d2335b8","title":"Book 2 · Unit 5 · RW · READING 2","subtitle":"READING 2 · source slide 129","duration":146.39,"cues":[{"start":0,"end":5.12,"text":"Tough Guy – A Race to the Limit What is Tough Guy?","coverage":1},{"start":6.22,"end":12.64,"text":"Every January, more than three ,000 people take part in one of the most difficult races on Earth,","coverage":1},{"start":13.26,"end":15.82,"text":"the Tough Guy competition in the UK.","coverage":1},{"start":16.86,"end":17.94,"text":"Participants run,","coverage":1},{"start":18.3,"end":18.68,"text":"swim,","coverage":1},{"start":19.04,"end":22.06,"text":"and climb across the 15 -kilometer course.","coverage":1},{"start":22.6,"end":23.66,"text":"But this is","coverage":1},{"start":23.66,"end":23.98,"text":"no","coverage":1},{"start":23.98,"end":24.84,"text":"normal race.","coverage":1},{"start":25.64,"end":28,"text":"These runners have to crawl through tunnels,","coverage":1},{"start":28.46,"end":30.08,"text":"run across a field of nettles,","coverage":1},{"start":30.5,"end":32.02,"text":"and jump over fire.","coverage":1},{"start":32.72,"end":33.44,"text":"What's more,","coverage":1},{"start":33.78,"end":35.92,"text":"the competition takes place in January,","coverage":1},{"start":36.3,"end":38.06,"text":"so temperatures are freezing,","coverage":1},{"start":38.58,"end":42.02,"text":"sometimes as low as minus six degrees centigrade.","coverage":1},{"start":43.08,"end":49.46,"text":"People travel from all over the world to take part, with participants from the United States, Australia,","coverage":1},{"start":49.8,"end":50.5,"text":"and China.","coverage":1},{"start":52,"end":53.98,"text":"Why do people take part?","coverage":1},{"start":55.12,"end":57.2,"text":"The competition is very dangerous,","coverage":1},{"start":57.56,"end":59.64,"text":"and every year there are accidents.","coverage":1},{"start":60.42,"end":63.44,"text":"Injuries like broken bones and cuts are common.","coverage":1},{"start":64.26,"end":65.96,"text":"The race is very hard.","coverage":1},{"start":66.54,"end":69.62,"text":"One third of participants do not finish it.","coverage":1},{"start":70.34,"end":72.38,"text":"Runners have to be fit and healthy.","coverage":1},{"start":73.14,"end":76.12,"text":"Most people train all year to prepare for the event.","coverage":1},{"start":76.12,"end":80,"text":"It is also the first race like it in the world.","coverage":1},{"start":80.84,"end":84.34,"text":"Many people take part in the competition because it is so famous.","coverage":1},{"start":85.1,"end":89.22,"text":"Every year the organizers change the event and add new things.","coverage":1},{"start":89.82,"end":93.74,"text":"This means that the competition stays exciting and challenging,","coverage":1},{"start":94.2,"end":96.84,"text":"so people go back year after year.","coverage":1},{"start":98.56,"end":99.52,"text":"The Course","coverage":1},{"start":100.36,"end":104.4,"text":"The diagram shows an example of the Tough Guy course.","coverage":1},{"start":105.12,"end":105.74,"text":"First,","coverage":1},{"start":106.5,"end":109.66,"text":"participants run for one kilometer along a muddy road.","coverage":1},{"start":110.48,"end":113.98,"text":"Next, they crawl under low nets on the ground.","coverage":1},{"start":114.88,"end":115.78,"text":"After the nets,","coverage":1},{"start":116.18,"end":121.6,"text":"the runners jump off a high platform into a lake and swim for another kilometer.","coverage":1},{"start":122.46,"end":124.88,"text":"Then they reach the field of fire.","coverage":1},{"start":125.8,"end":130.46,"text":"Here the runners run across a field and jump over small bonfires.","coverage":1},{"start":131.1,"end":131.64,"text":"Next,","coverage":1},{"start":132.48,"end":134.52,"text":"participants must crawl through a long tunnel.","coverage":1},{"start":135.32,"end":137.14,"text":"The tunnel is partly underwater.","coverage":1},{"start":138.22,"end":138.66,"text":"Finally,","coverage":1},{"start":139.14,"end":144.56,"text":"the runners run two kilometers through nettles before they reach the finish line.","coverage":1}],"file":"dae10e2335a57ea83a2a.js","track":0,"media":"../assets/media/2eee55d68d2335b8c2a38da0f3fe7608bdbd4ace96a2ce76213cff026d4629a4.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 You jump off a bridge.","slide":4,"shape":"16","bookPage":"104"},{"text":"2 They tie a rope to your body.","slide":4,"shape":"17","bookPage":"104"},{"text":"3 Bungee jumping is an exciting sport.","slide":5,"shape":"10","bookPage":"104"},{"text":"4 It is not a good idea to bungee jump in bad weather.","slide":5,"shape":"11","bookPage":"104"},{"text":"1 What does the phrase ‘world record’ mean? Possible answer: A world record is the best performance of its kind in the world.","slide":7,"shape":"26","bookPage":"104"},{"text":"2 What world record do you think the man in the photos broke? Possible answer: He might have been the oldest person to do a bungee jump.","slide":7,"shape":"27","bookPage":"104"},{"text":"3 How do you think he felt before, during and after breaking the record? Possible answer: He may have felt nervous before the jump, frightened during it and excited afterwards.","slide":7,"shape":"28","bookPage":"104"},{"text":"1 The noise was so loud that it was deafening.","slide":15,"shape":"9","bookPage":"104"},{"text":"2 A difficult task can be called a challenge.","slide":15,"shape":"10","bookPage":"104"},{"text":"3 A person with a broken arm is injured.","slide":15,"shape":"11","bookPage":"104"},{"text":"4 Strong wind can make the rope shake.","slide":15,"shape":"12","bookPage":"104"},{"text":"5 A sudden pull can jerk your body.","slide":15,"shape":"13","bookPage":"104"},{"text":"6 Something that changes how you feel is an experience.","slide":15,"shape":"14","bookPage":"104"},{"text":"1 The world’s oldest / first bungee jumper jumped from the Bloukrans Bridge. Correct option: oldest.","slide":18,"shape":"18","bookPage":"105"},{"text":"2 Bungee jumping is a safe / dangerous sport. Correct option: dangerous.","slide":18,"shape":"19","bookPage":"105"},{"text":"3 Mohr Keet bungee jumped three / many times. Correct option: three.","slide":18,"shape":"20","bookPage":"105"},{"text":"1 The Bloukrans Bridge is 216 metres high.","slide":21,"shape":"17","bookPage":"105"},{"text":"2 The eyes, the back and the neck can be injured in a bungee jump.","slide":21,"shape":"18","bookPage":"105"},{"text":"3 Mohr was 88 years old when he did his first jump.","slide":22,"shape":"11","bookPage":"105"},{"text":"4 Mohr likes being afraid.","slide":22,"shape":"12","bookPage":"105"},{"text":"1 The Bloukrans Bridge is one of the shortest bungee jumps. False. Corrected sentence: The Bloukrans Bridge is one of the highest bungee jumps in the world.","slide":25,"shape":"17","bookPage":"105"},{"text":"2 Bungee ropes often break. False. Corrected sentence: Bungee ropes do not often break.","slide":25,"shape":"18","bookPage":"105"},{"text":"3 Mohr’s second jump was when he was 93. True.","slide":26,"shape":"11","bookPage":"105"},{"text":"4 Mohr wanted to break a world record. False. Corrected sentence: Mohr did not know he was going to break a world record when he jumped.","slide":26,"shape":"12","bookPage":"105"},{"text":"6 Work with a partner. Discuss the questions below.1 How do you feel about older people doing dangerous sports? Why?2 What are three things you should do before you try a dangerous sport?Possible answers1 I think older people can enjoy new challenges, but they should consider their health and the risks.2 I would find a qualified instructor, check whether the activity is suitable for me and learn the safety rules.","slide":28,"shape":"14","bookPage":"105"},{"text":"4 The first cricket game I ever saw was strange because I didn’t understand the\nrules. Once I learnt more about the sport, I became a big fan.","slide":39,"shape":"8","bookPage":"106"},{"text":"5 In baseball, players must be able to throw the ball a long distance directly to\nanother player.","slide":39,"shape":"9","bookPage":"106"},{"text":"1 What is the main topic of the text? a unusual competitions / b unusual sports / c popular sports. Correct option: b unusual sports.","slide":50,"shape":"17","bookPage":"107"},{"text":"2 Where do the events in the text happen? a in one country / b around the world / c in a city. Correct option: b around the world.","slide":50,"shape":"18","bookPage":"107"},{"text":"3 What types of words are the underlined words? a verbs / b adjectives / c articles / d nouns / e prepositions. Correct options: b adjectives and d nouns.","slide":50,"shape":"19","bookPage":"107"},{"text":"1 Wrestling is a sport in which two people try to push each other to the ground.","slide":54,"shape":"8","bookPage":"108"},{"text":"2 A person with bare feet is not wearing shoes.","slide":54,"shape":"9","bookPage":"108"},{"text":"Paragraph 2: e Coney Island Polar Bear Plunge","slide":64,"shape":"17","bookPage":"109"},{"text":"Paragraph 3: b Dragon boat racing","slide":64,"shape":"18","bookPage":"109"},{"text":"Paragraph 4: d Caber toss","slide":64,"shape":"19","bookPage":"109"},{"text":"Paragraph 5: a Fireball football","slide":65,"shape":"14","bookPage":"109"},{"text":"Paragraph 6: c Toe wrestling","slide":65,"shape":"15","bookPage":"109"},{"text":"1 Fireball football is popular in Indonesia.","slide":74,"shape":"7","bookPage":"109"},{"text":"2 Dragon boat racing is popular in Singapore, China, Malaysia and Indonesia.","slide":74,"shape":"8","bookPage":"109"},{"text":"3 Toe wrestling is popular in England.","slide":74,"shape":"9","bookPage":"109"},{"text":"4 Caber toss is popular in Scotland.","slide":74,"shape":"10","bookPage":"109"},{"text":"5 Coney Island Polar Bear Plunge is popular in the USA.","slide":74,"shape":"11","bookPage":"109"},{"text":"The Coney Island Polar Bear Plunge takes place every Sunday from October to April and on Independence Day. Corrected sentence: The Coney Island Polar Bear Plunge takes place every Sunday from October to April and on New Year’s Day.","slide":76,"shape":"14","bookPage":"109"},{"text":"The Coney Island Polar Bear Plunge began in 2003. Corrected sentence: The Coney Island Polar Bear Plunge began in 1903.","slide":76,"shape":"15","bookPage":"109"},{"text":"A dragon boat has a dragon’s tail painted on it. Corrected sentence: A dragon boat has a dragon’s head painted on it.","slide":83,"shape":"14","bookPage":"109"},{"text":"There are 25 people in each dragon boat team. Corrected sentence: There are 22 people in each dragon boat team.","slide":83,"shape":"15","bookPage":"109"},{"text":"A caber is a large piece of metal. Corrected sentence: A caber is a large piece of wood.","slide":85,"shape":"14","bookPage":"109"},{"text":"A caber is usually the size of a large tree. Corrected sentence: A caber is usually the size of a small tree.","slide":85,"shape":"15","bookPage":"109"},{"text":"In fireball football, the ball is made from plastic. Corrected sentence: In fireball football, the ball is made from coconut shells.","slide":90,"shape":"14","bookPage":"109"},{"text":"The ball is on fire only at the beginning of a game of fireball football. Corrected sentence: The ball is on fire throughout a game of fireball football.","slide":90,"shape":"15","bookPage":"109"},{"text":"The world toe wrestling competition happens twice a year. Corrected sentence: The world toe wrestling competition happens every year.","slide":92,"shape":"14","bookPage":"109"},{"text":"In toe wrestling, only one hand must stay on the floor. Corrected sentence: In toe wrestling, both hands must stay on the floor.","slide":92,"shape":"15","bookPage":"109"},{"text":"7 Answer the questions.1 What kind of person is this text for?a somebody who is interested in different sportsb somebody who wants to learn how to play a new sport2 Where do you think you might see this text?a in a newspaper or magazineb on a website3 What do you think the text is?a an advert b an articleAnswers1 a somebody who is interested in different sports2 b on a website3 b an article","slide":103,"shape":"17","bookPage":"110"},{"text":"1. Summary gap 1\nAnswer: evening","slide":106,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: ii","slide":106,"shape":"8","bookPage":null},{"text":"course: the route for the competition; challenging: testing your ability.","slide":116,"shape":"18","bookPage":"111"},{"text":"fit: healthy and strong; accidents: unexpected events that may cause injury or damage.","slide":116,"shape":"19","bookPage":"111"},{"text":"climb: go up or onto something; participant: someone who takes part.","slide":116,"shape":"20","bookPage":"111"},{"text":"2 Work with a partner. Read the emails again and look at the diagram. Discuss the questions below.1 What do you think happens in the Tough Guy competition?2 In your opinion, what kind of people participate in the Tough Guy competition?Possible answers1 It looks like a running competition outside, with many difficult obstacles.2 I think strong, healthy people take part in the Tough Guy competition.","slide":121,"shape":"15","bookPage":"111"},{"text":"The Tough Guy competition starts with a mud run. Next, participants crawl under low nets on the ground.","slide":124,"shape":"17","bookPage":"111"},{"text":"Then, they reach the field of fire. Here, the participants run across a field and jump over small fires.","slide":124,"shape":"18","bookPage":"111"},{"text":"Next, they must crawl through a long water tunnel.","slide":125,"shape":"11","bookPage":"111"},{"text":"Finally, they run two kilometres through nettles before they reach the finish line.","slide":125,"shape":"12","bookPage":"111"},{"text":"4 Work with a partner. Look at the diagram in Exercise 1 and the box below. Check the meaning of the verbs. Then take turns to describe the obstacles on the Tough Guy course.Possible answerFirst, participants run through mud. Next, they crawl under low nets.After the nets, they jump off a high platform and swim across a lake.Then, they run across a field and jump over small fires.","slide":127,"shape":"17","bookPage":"113"},{"text":"4 Work with a partner. Describe the remaining obstacles on the Tough Guy course.Possible answerNext, participants must crawl through a water tunnel. Finally, they run through nettles.","slide":128,"shape":"11","bookPage":"113"},{"text":"1 Tough Guy is an easy / a difficult competition. Correct option: a difficult.","slide":135,"shape":"17","bookPage":"113"},{"text":"2 It takes place when the weather is hot / cold. Correct option: cold.","slide":135,"shape":"18","bookPage":"113"},{"text":"3 It is popular with people from the UK / all over the world. Correct option: all over the world.","slide":136,"shape":"11","bookPage":"113"},{"text":"4 Every year people get hurt / go home early. Correct option: get hurt.","slide":136,"shape":"12","bookPage":"113"},{"text":"6 Read the text again. Underline important details in Paragraph 1. Every January, more than 3,000 people take part in one of the most difficult races on Earth: the Tough Guy competition in the UK. Participants run, swim and climb across the 15-kilometre course. But this is no normal race. These runners have to crawl through tunnels, run across a field of nettles and jump over fire. What’s more, the competition takes place in January, so temperatures are freezing – sometimes as low as −6 °C. People travel from all over the world to take part, with participants from the US, Australia and China.","slide":142,"shape":"18","bookPage":"113"},{"text":"Paragraph 2: The competition is very dangerous and every year there are accidents. Injuries like broken bones and cuts are common. The race is very hard: one-third of participants do not finish it. Runners have to be fit and healthy. Most people train all year to prepare for the event. It is also the first race like it in the world. Many people take part in the competition because it is so famous. Every year, the organizers change the event and add new things. This means that the competition stays exciting and challenging, so people go back year after year.","slide":143,"shape":"18","bookPage":"113"},{"text":"Paragraph 3: The diagram shows an example of the Tough Guy course. First, participants run for one kilometre along a muddy road. Next, they crawl under low nets on the ground. After the nets, the runners jump off a high platform into a lake and swim for another kilometre. Then they reach the field of fire. Here the runners run across a field and jump over small bonfires. Next, participants must crawl through a long tunnel. The tunnel is partly underwater. Finally, the runners run two kilometres through nettles before they reach the finish line.","slide":144,"shape":"18","bookPage":"113"},{"text":"7 Why does the competition take place in January? a so that more people from around the world can take part / b to make the competition easier / c to make the competition more difficult. Correct option: c to make the competition more difficult.","slide":150,"shape":"11","bookPage":"113"},{"text":"1 Walk over the bridge.","slide":153,"shape":"7","bookPage":"114"},{"text":"2 Go past the school.","slide":155,"shape":"7","bookPage":"114"},{"text":"3 Drive through the tunnel.","slide":157,"shape":"7","bookPage":"114"},{"text":"4 Go across the road.","slide":159,"shape":"7","bookPage":"114"},{"text":"5 Walk around the park.","slide":161,"shape":"7","bookPage":"114"},{"text":"6 Go along the street.","slide":163,"shape":"7","bookPage":"114"},{"text":"7 Walk under the bridge.","slide":165,"shape":"7","bookPage":"114"},{"text":"It is easy to get to my house. First, walk (1) along the High Street. Go (2)\npast the bank and (3) over the bridge. Then walk (4) through the\npark and (5) under the next bridge.","slide":168,"shape":"7","bookPage":"115"},{"text":"Go (6) through the tunnel – watch out for cars – and walk (7) across the road.\nWalk (8) around the lake. My house is at the end of the road. It’s the pink one!","slide":168,"shape":"8","bookPage":"115"},{"text":"Option a, classroom. Possible answer: First, go along the corridor. Go past the office and then walk up the stairs. It is the first door on the left.","slide":170,"shape":"16","bookPage":"115"},{"text":"Option b, toilets. Possible answer: Leave the classroom and go past three more classrooms. Walk around the corner and you will find them at the end of the corridor.","slide":170,"shape":"17","bookPage":"115"},{"text":"Option c, canteen. Possible answer: Enter the building and walk past the office and the stairs. Go through the door at the back. Walk across the playground and go through the big door.","slide":170,"shape":"18","bookPage":"115"},{"text":"The cyclists ride along the path.","slide":174,"shape":"6","bookPage":null},{"text":"The swimmers move through the water.","slide":174,"shape":"9","bookPage":null},{"text":"Walk along the path to the gate. Go through that gate into the sports ground. The court is on your right inside the ground.","slide":175,"shape":"6","bookPage":null},{"text":"The runners cross the first field. At the end of that field, they turn towards a bridge. They go over the bridge to the finish.","slide":176,"shape":"6","bookPage":null},{"text":"The participant is running along a mountain path. He is moving past the orange cones.","slide":177,"shape":"7","bookPage":null},{"text":"The participant can follow the path past the cones. Then they can reach the next marker.","slide":177,"shape":"10","bookPage":null},{"text":"1. Few beginners used the hall at first.\nAnswer: TRUE","slide":182,"shape":"5","bookPage":null},{"text":"11. The hall looks at return visits, not just attendance totals.\nAnswer: G","slide":182,"shape":"8","bookPage":null},{"text":"1. Summary gap 1\nAnswer: decisions","slide":185,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: vi","slide":185,"shape":"8","bookPage":null},{"text":"The participants go through a narrow gate.","slide":193,"shape":"6","bookPage":null},{"text":"The route takes runners under a bridge.","slide":193,"shape":"9","bookPage":null},{"text":"The course begins beside the school. From the school, runners go past a shop. After passing the shop, they cross the bridge.","slide":194,"shape":"6","bookPage":null},{"text":"The cyclist approaches the red cone. She rides around it without stopping. After the turn, she follows the path back.","slide":195,"shape":"6","bookPage":null},{"text":"A cyclist is riding along a path beside the water. Orange cones mark parts of the route. The cyclist is moving past one of the cones.","slide":196,"shape":"7","bookPage":null},{"text":"First, the cyclist rides past the cones. Next, he could follow the path between the trees. Finally, he could stop at an imagined finish point.","slide":197,"shape":"7","bookPage":null},{"text":"1 bridge","slide":201,"shape":"11","bookPage":"116"},{"text":"2 swimming route","slide":201,"shape":"12","bookPage":"116"},{"text":"3 tunnel","slide":201,"shape":"13","bookPage":"116"},{"text":"4 cycling route","slide":201,"shape":"14","bookPage":"116"},{"text":"5 central library","slide":201,"shape":"15","bookPage":"116"},{"text":"6 running route","slide":201,"shape":"16","bookPage":"116"},{"text":"1 The participants have to run 10 kilometres.","slide":205,"shape":"16","bookPage":"117"},{"text":"2 The participants have to swim 1,500 metres.","slide":205,"shape":"17","bookPage":"117"},{"text":"3 The participants have to cycle 40 kilometres.","slide":205,"shape":"18","bookPage":"117"},{"text":"a cycle over / across the bridge","slide":207,"shape":"6","bookPage":"117"},{"text":"b cycle through the tunnel","slide":207,"shape":"7","bookPage":"117"},{"text":"c run along the road","slide":207,"shape":"8","bookPage":"117"},{"text":"d swim across the bay","slide":207,"shape":"9","bookPage":"117"},{"text":"e cycle past the central library","slide":207,"shape":"10","bookPage":"117"},{"text":"a cycle over / across the bridge  : 4","slide":210,"shape":"6","bookPage":"117"},{"text":"b cycle through the tunnel  : 3","slide":210,"shape":"7","bookPage":"117"},{"text":"c run along the road  : 5","slide":210,"shape":"8","bookPage":"117"},{"text":"d swim across the bay  : 1","slide":210,"shape":"9","bookPage":"117"},{"text":"e cycle past the central library  : 2","slide":210,"shape":"10","bookPage":"117"},{"text":"1 The boys and girls play sports every day at school.","slide":215,"shape":"18","bookPage":"118"},{"text":"2 We watch swimming competitions on television.","slide":215,"shape":"19","bookPage":"118"},{"text":"3 Dragon boat racing is popular in China, Malaysia and Indonesia.","slide":215,"shape":"20","bookPage":"118"},{"text":"1 Julia and Suki is tennis players. ✗ Correct form: Julia and Suki are tennis players.","slide":217,"shape":"6","bookPage":"118"},{"text":"2 The student swims every day. ✓","slide":217,"shape":"7","bookPage":"118"},{"text":"3 We cycles to school every day. ✗ Correct form: We cycle to school every day.","slide":217,"shape":"8","bookPage":"118"},{"text":"1 The weightlifter lifts the weight onto his shoulders. Picture b.","slide":220,"shape":"5","bookPage":"119"},{"text":"2 The weightlifter drops the weight to the ground. Picture d.","slide":220,"shape":"16","bookPage":"119"},{"text":"3 The weightlifter lifts the weight above his head. Picture c.","slide":220,"shape":"17","bookPage":"119"},{"text":"4 The weightlifter holds the weight above his head for as long as he can. Picture a.","slide":220,"shape":"18","bookPage":"119"},{"text":"a: 4","slide":221,"shape":"7","bookPage":"119"},{"text":"b: 1","slide":221,"shape":"9","bookPage":"119"},{"text":"c: 3","slide":221,"shape":"11","bookPage":"119"},{"text":"d: 2","slide":221,"shape":"13","bookPage":"119"},{"text":"First, the weightlifter lifts the weight onto his shoulders.","slide":224,"shape":"17","bookPage":"119"},{"text":"Next, the weightlifter lifts the weight above his head.","slide":224,"shape":"18","bookPage":"119"},{"text":"Then, the weightlifter holds the weight above his head for as long as he can.","slide":225,"shape":"11","bookPage":"119"},{"text":"Finally, the weightlifter drops the weight to the ground.","slide":225,"shape":"12","bookPage":"119"},{"text":"Possible answer: First, the tennis players walk onto the court. Next, the tennis players pick up their rackets. Then, one player hits the ball over the net. After that, the other player hits the ball back.","slide":227,"shape":"9","bookPage":"120"},{"text":"The high jump is an Olympic sport that is practised in many countries. Athletes competed in over 30 venues during the 2012 London Olympic Games. First, the high jumper runs towards the bar. It is important to run very fast. The high jump is a very important sport in some countries. Next, the high jumper jumps.","slide":232,"shape":"7","bookPage":"120"},{"text":"I was on the track-and-field team at school. The high jumper must jump from the right foot and keep their arms close to their sides. Then, the high jumper twists their body so that their back is to the bar. They must lift their head and feet and keep them high above the bar. The high jump is a really interesting sport. After that, the high jumper lands. They must be careful to land safely on the mat.","slide":233,"shape":"7","bookPage":"120"},{"text":"Mutaz Essa Barshim from Qatar and Gianmarco Tamberi from Italy both won the men’s gold medal at the Tokyo 2020 Olympics. They jumped 2.37 metres. It was the first time two people had shared a gold medal in athletics since 1912. Finally, the high jumper stands up, takes a bow and leaves the mat.","slide":234,"shape":"7","bookPage":"120"},{"text":"The players pass the ball to a partner.","slide":239,"shape":"6","bookPage":null},{"text":"Next, each swimmer enters the marked lane.","slide":239,"shape":"9","bookPage":null},{"text":"First, each player stands beside a cone. Next, the player rolls a ball through a gate. Finally, the player collects the ball and returns to the cone.","slide":240,"shape":"6","bookPage":null},{"text":"The participants begin by walking across the field. After crossing it, they follow the path around the lake. At the end of that path, they pass through the finish gate.","slide":241,"shape":"6","bookPage":null},{"text":"First, the runner carries the baton along the track. Next, the second runner waits in the handover area. Then the first runner gives the baton to the second runner. Finally, the second runner runs toward the finish.","slide":242,"shape":"7","bookPage":null},{"text":"A relay race needs clear teamwork and careful order. Each participant runs one part of the course. The baton moves from one runner to the next. This sequence helps the team complete the competition.","slide":243,"shape":"7","bookPage":null}];
